const j = $input.first().json;
const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const ex = j.execution || {}; const wf = j.workflow || {};
const err = ex.error || j.trigger?.error || {};
const html = `<div style="font-family:Arial,sans-serif;max-width:640px"><div style="background:#b3261e;color:#fff;padding:12px 16px;border-radius:8px 8px 0 0"><b>n8n-workflow mislukt</b></div><div style="border:1px solid #eee;border-top:0;padding:16px"><p><b>Workflow:</b> ${esc(wf.name)}</p><p><b>Node:</b> ${esc(ex.lastNodeExecuted)}</p><p><b>Fout:</b> ${esc(err.message)}</p>${err.description ? `<p style="color:#555">${esc(err.description)}</p>` : ''}${ex.url ? `<p><a href="${esc(ex.url)}">Uitvoering bekijken in n8n</a></p>` : ''}<p style="color:#888;font-size:12px">${new Date().toLocaleString('nl-NL', {timeZone: 'Europe/Amsterdam'})}</p></div></div>`;
return [{json: {subject: `🚨 n8n-fout: ${wf.name || 'onbekende workflow'}`, html}}];
